<script>const metadata=@json($metadata), rows=@json($rows); function copyExif(){navigator.clipboard.writeText(JSON.stringify(metadata,null,2)).then(()=>alert('EXIF copied to clipboard.'))} function save(data,name,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;a.click();URL.revokeObjectURL(a.href)} function downloadJson(){save(JSON.stringify(metadata,null,2),'exif-report.json','application/json')} function downloadCsv(){save(['Category,Property,Value',...rows.map(r=>[r.category,r.property,r.value].map(v=>'"'+String(v).replaceAll('"','""')+'"').join(','))].join('\n'),'exif-report.csv','text/csv')} @if($metadata['gps']['available'])const mapScript=document.createElement('script');mapScript.src='https://unpkg.com/leaflet@1.9.4/dist/leaflet.js';mapScript.onload=()=>{const map=L.map('map').setView([{{ $metadata['gps']['latitude'] }},{{ $metadata['gps']['longitude'] }}],13);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'&copy; OpenStreetMap'}).addTo(map);L.marker([{{ $metadata['gps']['latitude'] }},{{ $metadata['gps']['longitude'] }}]).addTo(map)};document.head.appendChild(mapScript);@endif</script>
